// waza_name is the move script, e.g. "vka0023".
// MakeKsnFileName turns it into the Fighting Spirit ID "ck0023".
local waza_name = "vka0023";
local wh = [0, 0];
if (IsKsnName(waza_name))
{
	local fn = MakeKsnFileName(waza_name);
	CMND_2DO_CREATE_AVA_TELOP("skill_name", "avatar_name", 0, 12, 0, fn, wh, iAvaPetNameSize, 6);
}

// Pass two arrays to get both sizes, then show both captions.
local mainSize = [0, 0];
local subSize = [0, 0];
CMND_2DO_CREATE_AVA_TELOP("skill_name", "avatar_name", 0, 12, 0, "ck0023", mainSize, subSize, 6);
CMND_2DO_STATE_DRAW_TELOP("skill_name", true);
CMND_2DO_STATE_DRAW_TELOP("avatar_name", true);
CMND_2DO_POS_SET_TELOP("avatar_name", 200 - subSize[0] / 2, 180);
